"use client";
import { useState } from 'react';
import { Sidebar } from '@/components/Sidebar';
import { TopBar } from '@/components/TopBar';
import { KpiGrid } from '@/components/KpiGrid';
import { RevenueChart } from '@/components/RevenueChart';
import { TransactionsTable } from '@/components/TransactionsTable';

export default function App() {
  const [sidebarOpen, setSidebarOpen] = useState(true);

  return (
    <div className="flex h-screen bg-gray-950 text-gray-100 font-sans overflow-hidden">
      <Sidebar open={sidebarOpen} onToggle={() => setSidebarOpen(o => !o)} />
      <div className="flex flex-col flex-1 overflow-hidden">
        <TopBar onMenuClick={() => setSidebarOpen(o => !o)} />
        <main className="flex-1 overflow-y-auto p-6 space-y-6">
          <div>
            <h2 className="text-2xl font-bold text-white">Analytics Overview</h2>
            <p className="text-gray-400 text-sm mt-1">Track performance across all key metrics</p>
          </div>
          <KpiGrid />
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
              <RevenueChart />
            </div>
            <TransactionsTable />
          </div>
        </main>
      </div>
    </div>
  );
}

/components/Sidebar.tsx.content:
import { BarChart2, Home, Users, Settings, CreditCard, Bell, ChevronLeft, ChevronRight } from 'lucide-react';

const NAV = [
  { icon: Home,       label: 'Overview',      active: true },
  { icon: BarChart2,  label: 'Analytics' },
  { icon: Users,      label: 'Customers',     badge: 24 },
  { icon: CreditCard, label: 'Billing' },
  { icon: Bell,       label: 'Notifications', badge: 3 },
  { icon: Settings,   label: 'Settings' },
];

interface SidebarProps { open: boolean; onToggle: () => void; }

export function Sidebar({ open, onToggle }: SidebarProps) {
  return (
    <aside className={`flex flex-col bg-gray-900 border-r border-gray-800 transition-all duration-300 relative flex-shrink-0 ${open ? 'w-56' : 'w-16'}`}>
      <div className={`flex items-center h-16 px-4 border-b border-gray-800 ${open ? 'justify-between' : 'justify-center'}`}>
        {open && <span className="font-bold text-lg text-indigo-400 tracking-tight">Metrics</span>}
        <button onClick={onToggle} className="p-1.5 rounded-lg hover:bg-gray-800 text-gray-400 transition-colors">
          {open ? <ChevronLeft className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
        </button>
      </div>
      <nav className="flex-1 py-4 space-y-0.5">
        {NAV.map(({ icon: Icon, label, active, badge }) => (
          <button key={label} className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${active ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:bg-gray-800 hover:text-gray-100'} ${!open && 'justify-center px-2'}`}>
            <Icon className="h-4 w-4 flex-shrink-0" />
            {open && <>
              <span className="flex-1 text-left">{label}</span>
              {badge !== undefined && <span className="text-xs bg-indigo-500/20 text-indigo-300 px-1.5 py-0.5 rounded-full">{badge}</span>}
            </>}
          </button>
        ))}
      </nav>
    </aside>
  );
}

