  { label: 'Active Users',     value: '8,291',    change: '+6.7%',  up: true,  icon: Users,        gradient: 'from-sky-500 to-blue-600' },
  { label: 'Conversion Rate',  value: '3.42%',    change: '+0.8%',  up: true,  icon: TrendingUp,   gradient: 'from-emerald-400 to-teal-600' },
