}

/components/RevenueChart.tsx.content:
"use client";
import { useState } from 'react';

const DATA = [
  { month: 'Jan', revenue: 65000, expenses: 42000 },
  { month: 'Feb', revenue: 72000, expenses: 45000 },
  { month: 'Mar', revenue: 68000, expenses: 41000 },
  { month: 'Apr', revenue: 89000, expenses: 52000 },
  { month: 'May', revenue: 95000, expenses: 58000 },
  { month: 'Jun', revenue: 112000, expenses: 63000 },
  { month: 'Jul', revenue: 128000, expenses: 71000 },
];

const max = Math.max(...DATA.map(d => d.revenue));

export function RevenueChart() {
  const [hovered, setHovered] = useState<number | null>(null);

  return (
    <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="font-semibold text-white">Revenue vs Expenses</h3>
          <p className="text-sm text-gray-400 mt-0.5">Last 7 months</p>
        </div>
        <div className="flex items-center gap-4 text-xs">
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-sm bg-indigo-500" />Revenue</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-sm bg-gray-600" />Expenses</span>
        </div>
      </div>
      <div className="flex items-end gap-3 h-48">
        {DATA.map((d, i) => (
          <div key={d.month} className="flex-1 flex flex-col items-center gap-1" onMouseEnter={() => setHovered(i)} onMouseLeave={() => setHovered(null)}>
            <div className="w-full flex gap-0.5 items-end" style={{ height: '160px' }}>
              <div className="flex-1 rounded-t-sm bg-indigo-500 transition-all" style={{ height: `${(d.revenue / max) * 100}%`, opacity: hovered === i ? 1 : 0.85 }} />
              <div className="flex-1 rounded-t-sm bg-gray-700 transition-all" style={{ height: `${(d.expenses / max) * 100}%` }} />
            </div>
            <span className="text-xs text-gray-500">{d.month}</span>
            {hovered === i && (
              <div className="absolute -translate-y-20 bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-xs text-white shadow-xl pointer-events-none">
                <p className="text-indigo-400 font-semibold">${(d.revenue / 1000).toFixed(0)}k</p>
                <p className="text-gray-400">${(d.expenses / 1000).toFixed(0)}k</p>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

